/**
 * StampRallyDetailResponse is the body of GET /api/stamp-rallies/{id}: the event
 * (with stamps + prizes) plus its issued cards.
 */
export interface StampRallyDetailResponse {
  stamp_rally: StampRally;
  cards: StampRallyCard[];
}
/**
 * StampRallyCardResponse is the body of POST /api/stamp-rallies/{id}/cards
 * {action:"create_card"} - the issued card (with token).
 */
export interface StampRallyCardResponse {
  card: StampRallyCard;
}
/**
 * StampRallyLogsResponse is the body of GET /api/stamp-rallies/{id}/logs.
 */
export interface StampRallyLogsResponse {
  logs: StampRallyLogEntry[];
}
/**
 * PublicStampRally is the participant-facing rally summary (no passwords). IsActive
 * is computed against the current time.
 */
export interface PublicStampRally {
  id: number /* int64 */;
  title: string;
  card_image: string;
  not_stamped_image: string;
  details: string;
  redeem_instructions: string;
  redeem_image: string;
  available_from: string;
  available_to: string;
  is_active: boolean;
  /**
   * What finishing the card takes: "all" (every stamp) or "counts" (RequiredFood
   * food stamps + RequiredGame game stamps). Sent so the card can show progress
   * against the same rule the server applies.
   */
  completion_mode: string;
  required_food: number /* int */;
  required_game: number /* int */;
  /**
   * FestivalLink is the path segment of the festival this rally is filed under -
   * its shortcode, or its id - so the card can open the festival dashboard. ""
   * when the rally belongs to no festival or its map isn't published.
   */
  festival_link?: string;
}
/**
 * PublicStamp is one stamp slot in the participant-facing card. AffiliateName ""
 * renders as "Senpan Tea House" on the frontend. Availability/collection are
 * computed against the current time.
 */
export interface PublicStamp {
  id: number /* int64 */;
  affiliate_name: string;
  /**
   * OccupantID is the festival-map occupant the stamp belongs to (nil when the
   * rally is not on a map), so the map can mark the stalls already collected.
   */
  occupant_id?: number /* int64 */;
  stamp_type: string; // "food" | "game"
  image: string;
  placement: Placement;
  active_from: string;
  active_to: string;
  available: boolean;
  /**
   * Expired reports that the stamp can never be collected again (its own window
   * ended, or the event did), as opposed to merely closed right now. The card uses
   * it to tell a participant when a per-type requirement has gone out of reach,
   * which is otherwise indistinguishable from a stall that reopens later.
   */
  expired: boolean;
  collected: boolean;
  collected_at: string;
}
/**
 * PublicPrize always carries the placement so the card can show the not-stamped
 * placeholder at the slot; Name/Image are populated only once the card is complete.
 */
export interface PublicPrize {
  id: number /* int64 */;
  name: string;
  image: string;
  placement: Placement;
}
/**
 * PublicStampCard is the full participant-facing card view returned for a token.
 */
export interface PublicStampCard {
  rally: PublicStampRally;
  participant_name: string;
  completed: boolean;
  completed_at: string;
  stamps: PublicStamp[];
  prizes: PublicPrize[];
  prizes_revealed: boolean;
}
/**
 * StampSubmitResponse is the body of POST /api/stamp-card/{token}/stamp: the
 * refreshed public card plus the id of the stamp just collected.
 */
export interface StampSubmitResponse {
  card: PublicStampCard;
  collected_stamp_id: number /* int64 */;
}
/**
 * SignupRally is one rally on the public sign-up page: enough to describe the
 * event and set expectations, with no passwords, no card list and no participant
 * names. GaraponTitle is set when an open Garapon is linked to the rally, in which
 * case signing up also issues a drawing link for it.
 */
export interface SignupRally {
  id: number /* int64 */;
  title: string;
  card_image: string;
  details: string; // markdown
  available_from: string;
  available_to: string;
  garapon_title?: string;
}
/**
 * SignupRalliesResponse is the body of GET /api/stamp-signup.
 */
export interface SignupRalliesResponse {
  rallies: SignupRally[];
}
/**
 * StampSignupResponse is the body of POST /api/stamp-signup/{id}: the tokens the
 * participant needs, which the client turns into links. GaraponToken is "" when the
 * rally has no open linked Garapon, and is otherwise a SEPARATE secret from
 * CardToken - the card link can be shared, the drawing link spends draws and
 * cannot. This response is the only time the drawing token is issued: no name-keyed
 * lookup returns it, so the client keeps it locally.
 */
export interface StampSignupResponse {
  participant_name: string;
  world: string;
  rally_title: string;
  card_token: string;
  garapon_token?: string;
  garapon_title?: string;
}
/**
 * StampLookupEntry is one rally a looked-up participant holds a card for.
 * There is deliberately no garapon token here. The lookup is keyed on a character
 * name, which is public, so it may report that draws exist and how many remain, but
 * never the token that spends them - that is issued once, at sign-up, and lives on
 * the participant's own device (or with staff). GaraponDrawsLeft is 0 when the
 * rally has no open linked garapon.
 */
export interface StampLookupEntry {
  rally_id: number /* int64 */;
  rally_title: string;
  card_token: string;
  /**
   * The name and world the card is actually held under, echoed back so the page
   * can show which record it found - a card issued before schema v66 may carry no
   * world, and one staff typed by hand may be spelled differently.
   */
  participant_name: string;
  world: string;
  garapon_title?: string;
  garapon_draws_left?: number /* int */;
  completed: boolean;
}
/**
 * StampLookupResponse is the body of POST /api/stamp-lookup. An unknown name and a
 * name with no cards return the same empty list - the endpoint never distinguishes
 * them, so it can't be used to probe who signed up.
 */
export interface StampLookupResponse {
  entries: StampLookupEntry[];
}

